Copy the workbook, read cached values from the active sheet, and build a lookup summing column I by (Stock, Year) from the basic table. Then write the matching sum, using 0 when there is no match or the log value is empty, into C3:C19. Save the output workbook.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals.active
ws = wb.active

def key_val(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return str(v)
    if isinstance(v, float) and v.is_integer():
        v = int(v)
    if isinstance(v, int):
        return str(v)
    return str(v).strip()

def num_val(v):
    if v is None:
        return 0.0
    if isinstance(v, bool):
        return float(v)
    if isinstance(v, (int, float)):
        return float(v)
    try:
        return float(str(v).strip())
    except Exception:
        return 0.0

basic = {}
for r in range(3, vws.max_row + 1):
    year = vws.cell(row=r, column=7).value
    stock = vws.cell(row=r, column=8).value
    log = vws.cell(row=r, column=9).value

    if year is None and stock is None:
        continue

    k = (key_val(stock), key_val(year))
    basic[k] = basic.get(k, 0.0) + num_val(log)

for r in range(3, 20):
    stock = vws.cell(row=r, column=1).value
    year = vws.cell(row=r, column=2).value
    k = (key_val(stock), key_val(year))
    val = basic.get(k, 0.0)
    if val == 0:
        val = 0.0
    ws.cell(row=r, column=3).value = val
    print(r, stock, year, val)

wb.save(OUT)
